  if(canPoster)resources.push(quickRow(icon('qr'),'Cartel de descarga del club','Hoja para imprimir y colocar en recepción','<a class="btn btn-ghost btn-sm" href="./assets/docs/Cartel_Guia_Rapida_Usuarios.png" target="_blank">Abrir</a>'));
